supplementalDiagnosticAttempt.command:
@'
import {API} from 'typescript/unstable/sync';
const root=process.cwd().replaceAll('\\','/');
const config=root+'/packages/clinical-content/tsconfig.json';
const api=new API({cwd:root});
try {
 const snapshot=api.updateSnapshot({openProjects:[config]});
 const project=snapshot.getProject(config);
 if(!project)throw Error('Clinical-content project not loaded');
 const paths=['question-topic-esophagus-structural-inflammatory-emergencies-20261111.ts','question-topic-esophagus-structural-inflammatory-emergencies-20261111.test.ts'].map(name=>root+'/packages/clinical-content/src/'+name);
 const diagnostics=paths.flatMap(file=>[...project.program.getSyntacticDiagnostics(file),...project.program.getSemanticDiagnostics(file)]);
 console.log(JSON.stringify(diagnostics.map(d=>({file:d.fileName,code:d.code,message:d.messageText,start:d.start})),null,2));
 console.log('Owned topic source/test diagnostics: '+diagnostics.length);
 process.exitCode=diagnostics.length?1:0;
 snapshot.dispose();
} finally {api.close();}
'@ | node --input-type=module
